#!/bin/sh
#
# PROVIDE: counter
# REQUIRE: NETWORKING FILESYSTEMS
# KEYWORD: shutdown
#
# Generated by infra for counter; do not hand-edit.
# shellcheck disable=SC2034 # rc.subr reads these variables

. /etc/rc.subr

name="counter"
rcvar="counter_enable"
load_rc_config "$name"
: "${counter_enable:=NO}"

app_user="counter"
envfile="/etc/counter/env"
logfile="/var/log/counter/counter.log"
start_cmd="counter_start"
stop_cmd="counter_stop"
status_cmd="counter_status"
extra_commands="migrate"
migrate_cmd="counter_migrate"
procname="/opt/counter/bin/counter"
pidfile="/var/run/counter/counter.pid"
supervisor_pidfile="/var/run/counter/supervisor.pid"

# The operator's env.
counter_env() {
    [ -r "$envfile" ] || { echo "$name: cannot read $envfile" >&2; return 1; }
    set -a
    # shellcheck disable=SC1090 # the operator's runtime configuration
    . "$envfile"
    HOME=/var/db/counter
    set +a
    # Every variable the app's env.template declares.
    for var in COUNTER_DATABASE_PATH COUNTER_LISTEN_ADDRESS; do
        eval "value=\${$var:-}"
        # shellcheck disable=SC2154 # assigned by the eval above
        case "$value" in
            ''|REPLACE_ME) echo "$name: $var is not set in $envfile" >&2; return 1 ;;
        esac
    done
}

counter_dirs() {
    mkdir -p /var/run/counter /var/log/counter
    chown "$app_user" /var/run/counter /var/log/counter
}

counter_start() {
    counter_dirs
    counter_env || return 1
    echo "Starting $name."
    # daemon -u resets the environment, so the env is sourced again after
    # privileges are dropped; the check above only refuses a bad file.
    /usr/sbin/daemon -c -f -P "$supervisor_pidfile" -p "$pidfile" -o "$logfile" \
        -u "$app_user" -- /bin/sh -c \
        "set -a; . $envfile; HOME=/var/db/counter; set +a; exec $procname serve"
}

counter_stop() {
    stopped=0
    for file in "$supervisor_pidfile" "$pidfile"; do
        [ -f "$file" ] || continue
        pid="$(cat "$file" 2>/dev/null)" || continue
        if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
            [ "$stopped" -eq 1 ] || echo "Stopping $name."
            kill "$pid" 2>/dev/null
            wait_for_pids "$pid"
            stopped=1
        fi
        rm -f "$file"
    done
    [ "$stopped" -eq 1 ] || { echo "$name not running."; return 1; }
}

counter_status() {
    if [ -f "$pidfile" ] && kill -0 "$(cat "$pidfile")" 2>/dev/null; then
        echo "$name is running as pid $(cat "$pidfile")."
    else
        echo "$name is not running."
        return 1
    fi
}

counter_migrate() {
    counter_env || return 1
    su -m "$app_user" -c "$procname migrate" </dev/null
}

run_rc_command "$1"
